<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){register_post_type('dre_case',['labels'=>['name'=>'Клинические случаи','singular_name'=>'Клинический случай','add_new_item'=>'Добавить клинический случай'],'public'=>false,'show_ui'=>true,'show_in_rest'=>false,'supports'=>['title','editor'],'menu_icon'=>'dashicons-images-alt2']);});
add_action('add_meta_boxes',function(){
 add_meta_box('dre-profile-bio','Подробная информация о специалисте',function($post){wp_nonce_field('dre_profile_details','dre_profile_nonce');$details=get_post_meta($post->ID,'_dre_profile_details',true)?:[];echo '<p>Заполняйте на языке этой страницы. Пустые разделы не показываются на сайте. Фотография задаётся через «Изображение записи».</p>';foreach(['focus'=>'Направления работы','education'=>'Образование','training'=>'Повышение квалификации','experience'=>'Опыт работы','approach'=>'Подход к работе','languages'=>'Языки общения'] as $key=>$label)echo '<p><label><strong>'.esc_html($label).'</strong><textarea rows="3" style="width:100%" name="dre_profile['.$key.']">'.esc_textarea($details[$key]??'').'</textarea></label></p>';},'dre_doctor');
 add_meta_box('dre-case-details','Данные клинического случая',function($post){wp_nonce_field('dre_case_details','dre_case_nonce');echo '<p>Добавляйте только реальные случаи с согласованными описанием и публикацией фотографий. На сайте показываются записи с обеими отметками и двумя фотографиями.</p>';foreach(['lang'=>'Язык описания (ru / lv / en)','service'=>'Ключ услуги (например service_implants)','doctor'=>'ID страницы врача','before'=>'ID фото до лечения из медиатеки','after'=>'ID фото после лечения из медиатеки'] as $key=>$label)echo '<p><label>'.esc_html($label).'<input style="width:100%" name="dre_case['.$key.']" value="'.esc_attr(get_post_meta($post->ID,'_dre_case_'.$key,true)).'"></label></p>';foreach(['permission'=>'Разрешение на публикацию получено','approved'=>'Клиника проверила и утвердила описание'] as $key=>$label)echo '<p><label><input type="checkbox" name="dre_case['.$key.']" value="1" '.checked(get_post_meta($post->ID,'_dre_case_'.$key,true),'1',false).'> '.esc_html($label).'</label></p>';},'dre_case');
});
add_action('save_post',function($id){
 if(wp_is_post_revision($id)||wp_is_post_autosave($id)||!current_user_can('edit_post',$id))return;
 if(get_post_type($id)==='dre_doctor'&&isset($_POST['dre_profile_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['dre_profile_nonce'])),'dre_profile_details')){$details=[];foreach(['focus','education','training','experience','approach','languages'] as $key)$details[$key]=wp_kses_post(wp_unslash($_POST['dre_profile'][$key]??''));update_post_meta($id,'_dre_profile_details',$details);}
 if(get_post_type($id)==='dre_case'&&isset($_POST['dre_case_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['dre_case_nonce'])),'dre_case_details')){foreach(['lang','service','doctor','before','after','permission','approved'] as $key){$v=wp_unslash($_POST['dre_case'][$key]??'');$v=in_array($key,['service','lang'],true)?sanitize_key($v):(in_array($key,['permission','approved'],true)?($v==='1'?'1':'0'):absint($v));if($key==='lang'&&!in_array($v,['ru','lv','en'],true))$v='ru';update_post_meta($id,'_dre_case_'.$key,$v);}}
});
